// vulkan-1.dll: the commands of vk_*.m by name, for vkGetInstanceProcAddr/vkGetDeviceProcAddr and as the DLL's
// exports (programs linked against the Vulkan SDK's vulkan-1.lib import them by name). The table is generated by
// tools/vk_dispatch.py.
#include "vk_impl.h"
#include "vx.h"
#include <string.h>

static const struct { const char *name; PFN_vkVoidFunction fn; int level; } g_commands[] = {
#include "vk_dispatch_table.h"
};
enum { COMMANDS = sizeof g_commands / sizeof g_commands[0] };

PFN_vkVoidFunction vk_lookup(const char *name, int level) {
    if (!name) return NULL;
    int lo = 0, hi = COMMANDS - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2, c = strcmp(name, g_commands[mid].name);
        if (!c) return g_commands[mid].level <= level ? g_commands[mid].fn : NULL;
        if (c < 0) hi = mid - 1; else lo = mid + 1;
    }
    if (vk_trace()) vx_log("vulkan: %s is not implemented", name);
    return NULL;
}

VKFN PFN_vkVoidFunction VKAPI_CALL vkGetInstanceProcAddr(VkInstance instance, const char *name) {
    if (name && !strcmp(name, "vkGetInstanceProcAddr")) return (PFN_vkVoidFunction)vkGetInstanceProcAddr;
    return vk_lookup(name, instance ? 2 : 0);
}
VKFN PFN_vkVoidFunction VKAPI_CALL vkGetDeviceProcAddr(VkDevice device, const char *name) {
    (void)device;
    if (name && !strcmp(name, "vkGetDeviceProcAddr")) return (PFN_vkVoidFunction)vkGetDeviceProcAddr;
    // (device commands only, as the specification asks)
    for (int i = 0; i < COMMANDS; i++) if (!strcmp(g_commands[i].name, name ? name : "")) return g_commands[i].level == 2 ? g_commands[i].fn : NULL;
    return NULL;
}

void vx_vulkan_init(void) {
    static vx_export exports[COMMANDS + 2];
    size_t n = 0;
    for (int i = 0; i < COMMANDS; i++) exports[n++] = (vx_export){ g_commands[i].name, (void *)g_commands[i].fn };
    exports[n++] = (vx_export){ "vkGetInstanceProcAddr", (void *)vkGetInstanceProcAddr };
    exports[n++] = (vx_export){ "vkGetDeviceProcAddr", (void *)vkGetDeviceProcAddr };
    vx_register_module("vulkan-1.dll", exports, n);
}

#ifdef __aarch64__
#include "thunks/vk_dispatch.m.inc"
#endif
